<script setup lang="ts">
import { ref, computed, onMounted, watch } from 'vue'
import { useRoute } from 'vue-router'
import { api, get, post, put } from '../../api/client'
import Drawer from '../../components/Drawer.vue'
import FormFields from '../../components/FormFields.vue'
import JsonView from '../../components/JsonView.vue'
import { toast } from '../../stores/toast'
const ask = (m: string) => window.confirm(m)
type Fld = { k: string; label: string; type?: 'text' | 'number' | 'bool' | 'select' | 'json' | 'list' | 'datetime'; options?: string[]; hint?: string; disabled?: boolean }
interface Def { title: string; note: string; list: string; rowsKey: string; key: string; save: (b: any, isNew: boolean) => Promise<any>; del?: (r: any) => string; cols: { k: string; l: string; f?: (r: any) => any }[]; fields: Fld[]; blank: any; extra?: { label: string; body: Fld[]; run: (b: any) => Promise<any>; blank: any }[]; rowActions?: { label: string; run: (r: any) => Promise<any>; confirm?: string }[] }
const iso = (v: any) => v ? new Date(typeof v === 'number' ? v * 1000 : v).toISOString().slice(0, 16) : ''
const unix = (s: string) => s ? Math.floor(new Date(s).getTime() / 1000) : null
const defs: Record<string, Def> = {
  hero_classes: { title: 'Hero classes', note: 'A class defines the slots a hero of that class can equip and its base stats; players own heroes, heroes equip items into slots.', list: '/v1/server/hero_classes', rowsKey: 'classes', key: 'id', save: (b, _n) => put(`/v1/server/hero_classes/${encodeURIComponent(b.id)}`, { ...b, slots: b.slots.split(',').map((s: string) => s.trim()).filter(Boolean), base_stats: JSON.parse(b.base_stats || '{}') }), del: (r) => `/v1/server/hero_classes/${encodeURIComponent(r.id)}`,
    cols: [{ k: 'id', l: 'Id' }, { k: 'name', l: 'Name' }, { k: 'slots', l: 'Slots', f: (r) => (r.slots ?? []).join(', ') }, { k: 'max_per_player', l: 'Max per player' }, { k: 'enabled', l: 'Enabled', f: (r) => r.enabled ? 'yes' : 'no' }], fields: [{ k: 'id', label: 'Id' }, { k: 'name', label: 'Name' }, { k: 'slots', label: 'Equipment slots', type: 'list', hint: 'weapon, helmet, …' }, { k: 'max_per_player', label: 'Max heroes of this class per player', type: 'number' }, { k: 'base_stats', label: 'Base stats (JSON)', type: 'json' }, { k: 'enabled', label: 'enabled', type: 'bool' }], blank: { id: '', name: '', slots: '', max_per_player: 1, base_stats: '{}', enabled: true } },
  crafting: { title: 'Crafting recipes', note: 'Inputs are consumed, outputs granted after the duration (0 = instant); station restricts where the recipe can be used.', list: '/v1/server/crafting/recipes', rowsKey: 'recipes', key: 'id', save: (b) => put('/v1/server/crafting/recipes', { ...b, inputs: JSON.parse(b.inputs || '[]'), outputs: JSON.parse(b.outputs || '[]'), duration_secs: Number(b.duration_secs) || 0 }), del: (r) => `/v1/server/crafting/recipes/${encodeURIComponent(r.id)}`,
    cols: [{ k: 'id', l: 'Id' }, { k: 'name', l: 'Name' }, { k: 'inputs', l: 'Inputs', f: (r) => (r.inputs ?? []).map((i: any) => `${i.item_id}×${i.amount}`).join(' + ') }, { k: 'outputs', l: 'Outputs', f: (r) => (r.outputs ?? []).map((i: any) => `${i.item_id}×${i.amount}`).join(' + ') }, { k: 'duration_secs', l: 'Duration (s)' }], fields: [{ k: 'id', label: 'Id' }, { k: 'name', label: 'Name' }, { k: 'inputs', label: 'Inputs (JSON [{item_id, amount}])', type: 'json' }, { k: 'outputs', label: 'Outputs (JSON [{item_id, amount}])', type: 'json' }, { k: 'duration_secs', label: 'Duration (s)', type: 'number' }, { k: 'station', label: 'Station (optional)' }], blank: { id: '', name: '', inputs: '[{"item_id":"","amount":1}]', outputs: '[{"item_id":"","amount":1}]', duration_secs: 0, station: '' } },
  coupons: { title: 'Coupons', note: 'A coupon code applied at checkout: percent or fixed discount, limited uses, optional expiry and store-item restriction.', list: '/v1/server/store/coupons', rowsKey: 'coupons', key: 'code', save: (b) => put('/v1/server/store/coupons', { ...b, value: Number(b.value), max_uses: Number(b.max_uses) || null, expires_at: unix(b.expires_at), store_items: b.store_items.split(',').map((s: string) => s.trim()).filter(Boolean) }), del: (r) => `/v1/server/store/coupons/${encodeURIComponent(r.code)}`,
    cols: [{ k: 'code', l: 'Code' }, { k: 'kind', l: 'Kind' }, { k: 'value', l: 'Value' }, { k: 'uses', l: 'Uses', f: (r) => `${r.uses ?? 0} / ${r.max_uses ?? '∞'}` }, { k: 'expires_at', l: 'Expires', f: (r) => r.expires_at ? iso(r.expires_at).replace('T', ' ') : '—' }], fields: [{ k: 'code', label: 'Code' }, { k: 'kind', label: 'Kind', type: 'select', options: ['percent', 'fixed', 'free_item'] }, { k: 'value', label: 'Value (percent or currency amount)', type: 'number' }, { k: 'max_uses', label: 'Max uses (0 = unlimited)', type: 'number' }, { k: 'expires_at', label: 'Expires', type: 'datetime' }, { k: 'store_items', label: 'Only for store items', type: 'list' }], blank: { code: '', kind: 'percent', value: 10, max_uses: 100, expires_at: '', store_items: '' } },
  entitlements: { title: 'Entitlements', note: 'Maps a platform purchase (Steam DLC app id, PSN entitlement, store SKU) to a reward table that is granted on login or on claim.', list: '/v1/server/entitlements', rowsKey: 'entitlements', key: 'external_id', save: (b) => put('/v1/server/entitlements', b), del: (r) => `/v1/server/entitlements/${encodeURIComponent(r.provider)}/${encodeURIComponent(r.external_id)}`,
    cols: [{ k: 'provider', l: 'Provider' }, { k: 'external_id', l: 'External id' }, { k: 'label', l: 'Label' }, { k: 'reward_table', l: 'Reward table' }, { k: 'license', l: 'License' }], fields: [{ k: 'provider', label: 'Provider', type: 'select', options: ['steam', 'epic', 'psn', 'xbox', 'nintendo', 'apple', 'google', 'custom'] }, { k: 'external_id', label: 'External id (app / SKU)' }, { k: 'label', label: 'Label' }, { k: 'reward_table', label: 'Reward table granted' }, { k: 'license', label: 'License', type: 'select', options: ['full', 'trial', 'subscription'] }], blank: { provider: 'steam', external_id: '', label: '', reward_table: '', license: 'full' },
    extra: [{ label: 'Grant to player', blank: { account_id: '', provider: 'steam', external_id: '' }, body: [{ k: 'account_id', label: 'Account id' }, { k: 'provider', label: 'Provider' }, { k: 'external_id', label: 'External id' }], run: (b) => post('/v1/server/entitlements/grant', b) }, { label: 'Revoke from player', blank: { account_id: '', provider: 'steam', external_id: '' }, body: [{ k: 'account_id', label: 'Account id' }, { k: 'provider', label: 'Provider' }, { k: 'external_id', label: 'External id' }], run: (b) => post('/v1/server/entitlements/revoke', b) }] },
  reward_modifiers: { title: 'Reward modifiers', note: 'Multiplies the rewards of the listed tables (all if empty) inside the window for the audience — double-XP weekends without touching tables.', list: '/v1/server/rewards/modifiers', rowsKey: 'modifiers', key: 'id', save: (b) => put('/v1/server/rewards/modifiers', { ...b, multiplier: Number(b.multiplier), starts_at: unix(b.starts_at), ends_at: unix(b.ends_at), tables: b.tables.split(',').map((s: string) => s.trim()).filter(Boolean), audience: b.audience || null }), del: (r) => `/v1/server/rewards/modifiers/${encodeURIComponent(r.id)}`,
    cols: [{ k: 'id', l: 'Id' }, { k: 'name', l: 'Name' }, { k: 'multiplier', l: '×' }, { k: 'tables', l: 'Tables', f: (r) => (r.tables ?? []).join(', ') || 'all' }, { k: 'window', l: 'Window', f: (r) => `${r.starts_at ? iso(r.starts_at).replace('T', ' ') : '…'} → ${r.ends_at ? iso(r.ends_at).replace('T', ' ') : '…'}` }, { k: 'audience', l: 'Audience', f: (r) => r.audience ?? 'everyone' }], fields: [{ k: 'id', label: 'Id' }, { k: 'name', label: 'Name' }, { k: 'multiplier', label: 'Multiplier', type: 'number' }, { k: 'tables', label: 'Reward tables (empty = all)', type: 'list' }, { k: 'starts_at', label: 'Starts', type: 'datetime' }, { k: 'ends_at', label: 'Ends', type: 'datetime' }, { k: 'audience', label: 'Audience (optional)' }], blank: { id: '', name: '', multiplier: 2, tables: '', starts_at: '', ends_at: '', audience: '' } },
  ads: { title: 'Ad placements', note: 'Rewarded-video placements: the client reports a completed view, the server checks cooldown and daily cap and grants the reward table. Trust client skips SSV callbacks (dev only).', list: '/v1/server/ad_placements', rowsKey: 'placements', key: 'id', save: (b) => put(`/v1/server/ad_placements/${encodeURIComponent(b.id)}`, { ...b, cooldown_secs: Number(b.cooldown_secs) || 0, daily_cap: Number(b.daily_cap) || 0, platforms: b.platforms.split(',').map((s: string) => s.trim()).filter(Boolean), metadata: JSON.parse(b.metadata || '{}') }), del: (r) => `/v1/server/ad_placements/${encodeURIComponent(r.id)}`,
    cols: [{ k: 'id', l: 'Id' }, { k: 'name', l: 'Name' }, { k: 'reward_table', l: 'Reward' }, { k: 'limits', l: 'Limits', f: (r) => `${r.daily_cap ?? 0}/day · ${r.cooldown_secs ?? 0}s cooldown` }, { k: 'platforms', l: 'Platforms', f: (r) => (r.platforms ?? []).join(', ') || 'all' }, { k: 'enabled', l: 'Enabled', f: (r) => r.enabled ? 'yes' : 'no' }], fields: [{ k: 'id', label: 'Id' }, { k: 'name', label: 'Name' }, { k: 'description', label: 'Description' }, { k: 'reward_table', label: 'Reward table' }, { k: 'cooldown_secs', label: 'Cooldown (s)', type: 'number' }, { k: 'daily_cap', label: 'Daily cap', type: 'number' }, { k: 'platforms', label: 'Platforms (empty = all)', type: 'list' }, { k: 'trust_client', label: 'trust client (no SSV)', type: 'bool' }, { k: 'enabled', label: 'enabled', type: 'bool' }, { k: 'metadata', label: 'Metadata (JSON)', type: 'json' }], blank: { id: '', name: '', description: '', reward_table: '', cooldown_secs: 300, daily_cap: 10, platforms: '', trust_client: false, enabled: true, metadata: '{}' } },
  content_tags: { title: 'Content tags', note: 'Tags on economy / content rows (items, currencies, store items…) — feature flags and remote config can switch whole tagged sets on and off.', list: '/v1/admin/content/tags', rowsKey: 'entries', key: 'id', save: (b) => put('/v1/admin/content/tags', { ...b, tags: b.tags.split(',').map((s: string) => s.trim()).filter(Boolean) }), del: (r) => `/v1/admin/content/tags/${encodeURIComponent(r.id)}`,
    cols: [{ k: 'table', l: 'Table' }, { k: 'id', l: 'Row id' }, { k: 'tags', l: 'Tags', f: (r) => (r.tags ?? []).join(', ') }], fields: [{ k: 'table', label: 'Table', type: 'select', options: ['items', 'currencies', 'store_items', 'reward_tables', 'quests', 'seasons'] }, { k: 'id', label: 'Row id' }, { k: 'tags', label: 'Tags', type: 'list' }], blank: { table: 'items', id: '', tags: '' } },
}
const route = useRoute(); const which = computed(() => String(route.meta.simple ?? route.path.split('/').pop())); const D = computed(() => defs[which.value])
const rows = ref<any[]>([]); const err = ref(''); const q = ref(''); const dlg = ref(''); const form = ref<any>({}); const isNew = ref(false); const ex = ref<any>(null); const raw = ref<any>(null)
async function load() { err.value = ''; rows.value = []; try { const r = await get(D.value.list); rows.value = r[D.value.rowsKey] ?? [] } catch (x: any) { err.value = x.message } }
onMounted(load); watch(which, load)
const view = computed(() => rows.value.filter((r) => !q.value || JSON.stringify(r).toLowerCase().includes(q.value.toLowerCase())))
function edit(r: any) { isNew.value = !r; raw.value = r; const b: any = { ...D.value.blank }; if (r) for (const f of D.value.fields) { const v = r[f.k]; b[f.k] = v == null ? b[f.k] : f.type === 'list' ? (Array.isArray(v) ? v.join(', ') : v) : f.type === 'json' ? JSON.stringify(v, null, 2) : f.type === 'datetime' ? iso(v) : v } form.value = b; dlg.value = 'edit' }
async function save() { try { await D.value.save({ ...form.value }, isNew.value); toast.show('saved'); dlg.value = ''; load() } catch (x: any) { toast.err(x) } }
async function del(r: any) { try { await api('DELETE', D.value.del!(r)); toast.show('deleted'); load() } catch (x: any) { toast.err(x) } }
async function runExtra() { try { const res = await ex.value.run({ ...form.value }); toast.show(res?.message ?? 'done'); dlg.value = ''; load() } catch (x: any) { toast.err(x) } }
</script>
<template>
  <div class="crumb"><span>{{ D.title }}</span><span class="id">{{ rows.length }}</span>
    <span style="margin-left:auto;display:flex;gap:8px"><input class="in" v-model="q" placeholder="filter" style="width:180px" /><button class="btn s" v-for="e in D.extra ?? []" :key="e.label" @click="ex = e; form = { ...e.blank }; dlg = 'extra'">{{ e.label }}</button><button class="btn s p" @click="edit(null)">New</button></span></div>
  <p class="err" v-if="err">{{ err }}</p>
  <div class="card">
    <p class="note">{{ D.note }}</p>
    <table><thead><tr><th v-for="c in D.cols" :key="c.k">{{ c.l }}</th><th style="width:110px"></th></tr></thead><tbody>
      <tr v-for="r in view" :key="r[D.key]"><td v-for="(c, i) in D.cols" :key="c.k" :class="{ m: i === 0 || c.k === 'id' || c.k === 'code', row: i === 0 }" @click="i === 0 && edit(r)">{{ c.f ? c.f(r) : r[c.k] ?? '—' }}</td><td><button class="btn s" @click="edit(r)">Edit</button> <button class="btn s" v-if="D.del" @click="ask('Delete?') && del(r)">×</button></td></tr>
      <tr v-if="!view.length"><td :colspan="D.cols.length + 1" class="empty">Nothing here yet</td></tr></tbody></table>
  </div>
  <Drawer v-if="dlg === 'edit'" :title="isNew ? `New — ${D.title}` : `${D.title}: ${form[D.key]}`" @close="dlg = ''"><div class="form">
    <FormFields :fields="D.fields.map((f) => ({ ...f, disabled: !isNew && f.k === D.key }))" :model="form" />
    <details v-if="raw" style="margin-top:8px"><summary class="dim">Raw record</summary><JsonView :value="raw" /></details>
    <div class="row"><button class="btn" @click="dlg = ''">Cancel</button><button class="btn p" :disabled="!form[D.key]" @click="save">Save</button></div></div></Drawer>
  <Drawer v-if="dlg === 'extra'" :title="ex.label" @close="dlg = ''"><div class="form"><FormFields :fields="ex.body" :model="form" /><div class="row"><button class="btn" @click="dlg = ''">Cancel</button><button class="btn p" @click="runExtra">Run</button></div></div></Drawer>
</template>
